let creationMode='template',fileAsset='',fileName='',fileRevision=0,readingFile=false,uploadPreviewKey='';
const baseFormData=formData,basePreview=updatePublishPreview,baseSubmit=publishForm.onsubmit;
document.querySelector('#publish-heading').textContent='Bring your playable idea to Slice.';
publishDialog.querySelector('h2+p').textContent='Import an interactive experience or start with a playable template.';
document.querySelector('.publish-notice').textContent='Local prototype · Experiences are saved in this browser only. They are not yet public or synced across devices.';
const modes=document.createElement('div');modes.className='creation-modes two-modes';modes.setAttribute('role','group');modes.setAttribute('aria-label','Interactive source');modes.innerHTML='<button type="button" data-mode="template" aria-pressed="true"><strong>✳ Playable template</strong><span>Start with a game or experiment</span></button><button type="button" data-mode="html" aria-pressed="false"><strong>↥ Interactive HTML</strong><span>Bring a self-contained playable project</span></button>';publishForm.before(modes);
const uploadFields=document.createElement('div');uploadFields.id='file-section';uploadFields.hidden=true;uploadFields.innerHTML=`<label class="drop-zone" id="drop-zone"><span class="upload-icon">↥</span><strong>Drop interactive HTML here, or choose a file</strong><span id="upload-hint"></span><input id="work-file" type="file" accept=".html,.htm" aria-label="Choose interactive HTML"></label><div id="file-info" role="status"></div><div id="html-help"><p class="field-help">One self-contained HTML / HTM file, up to 300 KB, with inline CSS and JavaScript. External resources, network requests, ZIP files, and project folders are not supported yet.</p><a class="sample-link" href="sample-interactive.html" download="color-playground.html">↓ Download example HTML</a><button type="button" id="load-example">Try the playable example</button></div>`;
document.querySelector('.publish-fields').prepend(uploadFields);const templateLabel=publishForm.elements.template.closest('label');const oldHelp=templateLabel.nextElementSibling;oldHelp.textContent='Six playable templates. No code required.';
formData=function(){return {...baseFormData(),contentType:'interactive',assetType:creationMode==='html'?'html':null,asset:creationMode==='html'?fileAsset:'',fileName:creationMode==='html'?fileName:''}};
updatePublishPreview=function(reset=false){if(creationMode==='template'){basePreview(reset);return}const d=formData();document.querySelector('#preview-title').textContent=d.title||'Your next playable idea';document.querySelector('#preview-desc').textContent=d.desc||'Describe what people can try and discover.';document.querySelector('#preview-author').textContent=d.author||'Curious Slicer';const key=[creationMode,fileRevision].join('|');if(!reset&&key===uploadPreviewKey)return;uploadPreviewKey=key;const host=document.querySelector('#publish-slice');host.dataset.template='';host.innerHTML=fileAsset?importedStage(d):'<div class="upload-empty"><span>↥</span><strong>Your experience starts here</strong><p>Import interactive HTML to try it before publishing.</p></div>'};
function setCreationMode(mode,clear=true){creationMode=mode==='html'?'html':'template';if(clear){fileAsset='';fileName='';fileRevision++;readingFile=false;document.querySelector('#work-file').value=''}document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===creationMode)));uploadFields.hidden=creationMode==='template';templateLabel.hidden=creationMode!=='template';oldHelp.hidden=creationMode!=='template';document.querySelector('#upload-hint').textContent='HTML / HTM · Playable experiences only · Up to 300 KB';document.querySelector('#file-info').textContent=fileName?'Selected: '+fileName:'';document.querySelector('#publish-error').textContent='';updatePublishPreview(true)}
function openCreator(work){let d=work||readStored(draftKey,null);const incomplete=d?.contentType==='interactive'&&d.assetType==='html'&&!d.asset;const legacy=d&&(d.assetType||d.contentType||d.postType||d.plainPost)&&!incomplete&&!isPublishableWork(d);publishForm.reset();setCreationMode('template');if(d&&!legacy){for(const [name,key] of [['title','title'],['description','desc'],['category','cat'],['template','template'],['author','author']])if(typeof d[key]==='string')publishForm.elements[name].value=d[key];if(!interactiveTemplates.includes(publishForm.elements.template.value))publishForm.elements.template.value='beat';fileAsset=typeof d.asset==='string'?d.asset:'';fileName=typeof d.fileName==='string'?d.fileName:'';fileRevision++;setCreationMode(d.assetType==='html'?'html':'template',false)}if(!publishDialog.open)publishDialog.showModal();updatePublishPreview(true);document.querySelector('#publish-error').textContent=legacy?'This older draft is not a playable experience. Start with interactive HTML or a playable template. The original draft is still stored in this browser.':''}
document.querySelector('#publish-entry').onclick=()=>openCreator();document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(b.dataset.mode!==creationMode)setCreationMode(b.dataset.mode)});
async function importFile(file){if(!file)return;const revision=++fileRevision;readingFile=true;fileAsset='';fileName='';document.querySelector('#publish-error').textContent='';document.querySelector('#file-info').textContent='Reading '+file.name+'…';updatePublishPreview(true);try{if(creationMode!=='html'||!/^.+\.html?$/i.test(file.name))throw Error('Choose a self-contained interactive HTML or HTM file. Image, text, document, and video posts are not supported.');if(!file.size||file.size>307200)throw Error('Choose a non-empty HTML file up to 300 KB.');const data=await file.text();if(!hasInteractiveRuntime(data))throw Error('No interactive behavior was detected. Import a playable HTML project with working controls, not a static page.');if(revision!==fileRevision||creationMode!=='html')return;fileAsset=data;fileName=file.name;document.querySelector('#file-info').textContent='✓ '+file.name+' · '+Math.max(1,Math.round(file.size/1024))+' KB';if(!publishForm.elements.title.value)publishForm.elements.title.value=file.name.replace(/\.[^.]+$/,'').slice(0,50);if(!publishForm.elements.description.value)publishForm.elements.description.value='Try this interactive experience.';updatePublishPreview(true)}catch(err){if(revision===fileRevision){document.querySelector('#publish-error').textContent=err.message;document.querySelector('#file-info').textContent='No playable project loaded.'}}finally{if(revision===fileRevision)readingFile=false}}
document.querySelector('#work-file').onchange=e=>importFile(e.target.files[0]);const drop=document.querySelector('#drop-zone');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging')};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');if(e.dataTransfer.files.length!==1){document.querySelector('#publish-error').textContent='Choose one interactive HTML file at a time.';return}importFile(e.dataTransfer.files[0])};
const exampleHtml=`<!doctype html><html lang="en"><meta charset="UTF-8"><style>body{margin:0;min-height:100vh;display:grid;place-content:center;text-align:center;background:#dfff85;color:#182517;font:16px system-ui}button{border:0;border-radius:30px;padding:14px 24px;background:#182517;color:white;font:inherit;cursor:pointer}h1{font-size:28px;margin:10px}p{margin:12px 0 24px}</style><body><p>COLOR PLAYGROUND</p><h1>What color is your day?</h1><p id="answer">Tap to discover a new mood.</p><button onclick="let a=['Inspired green','Sunset orange','Ocean blue','Berry pink'];let c=['#dfff85','#ffcf9b','#b2e2f5','#f5c2dc'];let i=Math.floor(Math.random()*4);document.body.style.background=c[i];document.getElementById('answer').textContent=a[i]">Change the mood ↗</button></body></html>`;
document.querySelector('#load-example').onclick=()=>{fileAsset=exampleHtml;fileName='color-playground.html';fileRevision++;readingFile=false;publishForm.elements.title.value='What color is your day?';publishForm.elements.description.value='Tap to give your day a different mood.';publishForm.elements.category.value='Creative';document.querySelector('#file-info').textContent='✓ Example loaded: '+fileName;document.querySelector('#publish-error').textContent='';updatePublishPreview(true)};
const saveDraft=document.querySelector('#save-draft').onclick;document.querySelector('#save-draft').onclick=()=>{if(readingFile){document.querySelector('#publish-error').textContent='Wait for the file to finish loading.';return}saveDraft()};
publishForm.onsubmit=e=>{const d=formData();if(readingFile||!isPublishableWork(d)){e.preventDefault();document.querySelector('#publish-error').textContent=readingFile?'Wait for the file to finish loading.':'Import a playable HTML project or choose an interactive template before publishing.';return}baseSubmit(e);if(!publishDialog.open)setCreationMode('template')};
